111: <script>
112: 'use strict';
113: (() => {
114: const canvas=document.getElementById('game'),ctx=canvas.getContext('2d',{alpha:false});
115: const ui={home:document.getElementById('homeScore'),away:document.getElementById('awayScore'),timer:document.getElementById('timer'),status:document.getElementById('statusText'),toast:document.getElementById('toast'),power:document.getElementById('power'),cooldown:document.getElementById('cooldown'),glueCool:document.getElementById('glueCool'),glueBtn:document.getElementById('glue'),glueStatus:document.getElementById('glueStatus'),select:document.getElementById('select'),end:document.getElementById('end')};
116: const cyan='#32f4ff',coral='#ff537c',purple='#b58aff',gold='#ffd75e',goldSoft='#ffe6a1';
117: const GLUE_TIME=3,GLUE_CD=10;
118: let W=0,H=0,dpr=1,field={},players=[],ball=null,particles=[],trails=[],score=[0,0],timeLeft=60,phase='play',phaseTimer=0,powerTimer=12,powerOrb=null,powerEffect=null,shake=0,last=0,elapsed=0,kickQueued=false,dashQueued=false,glueQueued=false;
119: let mode='pessi',started=false,glueMsg='',glueMsgTime=0;
120: const input={x:0,y:0,keys:{},joyId:null,joyOrigin:null};
121: const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),hypot=Math.hypot;
122: function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);field={x:Math.max(14,W*.055),y:Math.max(104,H*.14),w:W-Math.max(28,W*.11),h:H-Math.max(176,H*.21)-Math.max(104,H*.14)};field.r=Math.min(field.w,field.h)*.105;field.goalW=Math.min(field.w*.42,92);field.goalDepth=12;initEntities();}
123: function initEntities(){const cx=W/2,top=field.y+field.h*.22,bot=field.y+field.h*.78,humanPessi=mode==='pessi',aiPessi=mode==='pessi-ai';players=[makePlayer(cx,bot,cyan,0,true,humanPessi),makePlayer(cx-field.w*.22,bot-field.h*.13,cyan,0,false,aiPessi),makePlayer(cx,top,coral,1,false,false),makePlayer(cx+field.w*.22,top+field.h*.13,coral,1,false,false)];ball={x:cx,y:field.y+field.h/2,vx:rand(-18,18),vy:0,r:Math.max(7,Math.min(10,W*.023)),trail:[],glued:null};}
124: function makePlayer(x,y,color,team,human,pesi=false){return{x,y,vx:0,vy:0,r:Math.max(15,Math.min(20,W*.047)),color,team,human,pesi,glue:0,glueCd:0,deny:0,glueFx:0,faceX:0,faceY:team===0?-1:1,dash:0,dashCd:0,freeze:0,boost:0,kickFlash:0,kickCd:0,aiSeed:rand(0,10)}}
125: function resetPositions(){const cx=W/2,top=field.y+field.h*.22,bot=field.y+field.h*.78;players.forEach((p,i)=>{const positions=[[cx,bot],[cx-field.w*.22,bot-field.h*.13],[cx,top],[cx+field.w*.22,top+field.h*.13]][i];p.x=positions[0];p.y=positions[1];p.vx=p.vy=0;p.dash=0;p.kickFlash=0;p.glue=0;p.glueCd=0;p.deny=0;p.glueFx=0;});ball.x=cx;ball.y=field.y+field.h/2;ball.vx=rand(-15,15);ball.vy=0;ball.trail.length=0;ball.glued=null;}
126: function restart(){score=[0,0];timeLeft=60;phase='play';phaseTimer=0;powerTimer=12;powerOrb=null;powerEffect=null;particles=[];glueQueued=false;glueMsgTime=0;ui.end.classList.remove('show');ui.toast.classList.remove('show');resetPositions();updateHUD();}
127: function chooseMode(m){mode=m;initEntities();started=true;ui.select.classList.remove('show');restart();}
128: function showStarSelect(){started=false;restart();ui.select.classList.add('show');}
129: window.addEventListener('resize',resize,{passive:true});resize();
130: function updateHUD(){ui.home.textContent=String(score[0]).padStart(2,'0');ui.away.textContent=String(score[1]).padStart(2,'0');const timerSeconds=Math.ceil(timeLeft);ui.timer.textContent=`${Math.floor(timerSeconds/60)}:${String(timerSeconds%60).padStart(2,'0')}`;ui.status.textContent=phase==='goal'?'GOAL CELEBRATION':phase==='end'?'FULL TIME':powerEffect?powerEffect.label:'LIVE MATCH';if(powerEffect)ui.power.textContent=`✦  ${powerEffect.label} · ${Math.ceil(powerEffect.time)}s`;else if(powerOrb)ui.power.textContent='✦  POWER ORB · GRAB IT';else ui.power.textContent=`✦  POWER ORB IN ${Math.ceil(powerTimer)}`;ui.power.classList.toggle('active',!!powerOrb||!!powerEffect||powerTimer<5);
131: // Pessi ability HUD
132: const hp=players.find(p=>p.pesi&&p.human),ap=players.find(p=>p.pesi&&!p.human),sp=hp||ap;
133: ui.glueBtn.classList.toggle('hidden',!hp);
